/**
 * MONSTER HOOPS ACADEMY — 공통 네비게이션
 * - 네비: 로고(좌) | 토글(우)
 * - 온라인일 때만: 우측 하단 iOS 스타일 플로팅 로그인/로그아웃 버튼
 */
(function() {

  /* ── 채널톡 부트 (모든 페이지에서 한 번만 실행) ── */
  if (!window.ChannelIOInitialized) {
    (function(){
      var w=window;
      if(w.ChannelIO){return;}
      var ch=function(){ch.c(arguments);};ch.q=[];ch.c=function(args){ch.q.push(args);};w.ChannelIO=ch;
      function l(){
        if(w.ChannelIOInitialized){return;}
        w.ChannelIOInitialized=true;
        var s=document.createElement('script');s.type='text/javascript';s.async=true;
        s.src='https://cdn.channel.io/plugin/ch-plugin-web.js';
        var x=document.getElementsByTagName('script')[0];x.parentNode.insertBefore(s,x);
      }
      if(document.readyState==='complete'){l();}
      else{w.addEventListener('DOMContentLoaded',l);w.addEventListener('load',l);}
    })();
    ChannelIO('boot', {
      pluginKey: '4f478e17-56fc-4a0e-ae8c-b68c418e7da4',
      hideChannelButtonOnBoot: true
    }, function(error, user) {
      window.dispatchEvent(new Event('channelIOReady'));
    });
    // 부트 즉시 onBadgeChanged 등록 → count를 전역에 저장
    window._mhUnreadCount = 0;
    ChannelIO('onBadgeChanged', function(count) {
      window._mhUnreadCount = count;
      // 뱃지 DOM이 이미 있으면 바로 반영
      const badge = document.getElementById('mh-dm-badge');
      if (badge) {
        badge.style.display = count > 0 ? 'block' : 'none';
        badge.textContent = count > 99 ? '99+' : (count > 0 ? count : '');
      }
    });
  }

  const isOnline = location.pathname.includes('/online_academy');
  const root     = isOnline ? '../' : './';

  /* ── PWA 스탠드얼론 감지 ── */
  const isStandalone = window.navigator.standalone === true ||
    window.matchMedia('(display-mode: standalone)').matches;

  /* ── 스타일 ── */
  const style = document.createElement('style');
  style.textContent = `
    html, body { overscroll-behavior: none !important; }
    .site-nav {
      position: fixed !important;
      top: 0 !important; left: 0 !important; right: 0 !important;
      width: 100% !important; max-width: none !important;
      z-index: 9999 !important;
      background: transparent !important;
      border-bottom: none !important;
      height: auto !important;
      margin: 0 !important;
      padding: env(safe-area-inset-top, 0px) 0 0 !important;
      box-sizing: border-box !important;
      opacity: 0 !important;
      transition: opacity .2s ease !important;
    }
    .site-nav.mh-ready {
      opacity: 1 !important;
    }
    .site-nav.mh-hidden {
      opacity: 0 !important;
      transform: translateY(-100%) !important;
      pointer-events: none !important;
      transition: opacity .3s, transform .3s !important;
    }
    .site-nav-inner {
      width: 100% !important;
      max-width: none !important;
      margin: 0 !important;
      padding: 14px 24px !important;
      display: flex !important;
      align-items: center !important;
      justify-content: space-between !important;
      box-sizing: border-box !important;
      background: rgba(38,38,36,.85) !important;
      backdrop-filter: blur(16px) !important;
      -webkit-backdrop-filter: blur(16px) !important;
      border-bottom: 1px solid rgba(255,255,255,.08) !important;
    }
    .nav-logo {
      font-size: 15px !important;
      font-weight: 900 !important;
      letter-spacing: .06em !important;
      color: #fff !important;
      text-decoration: none !important;
      white-space: nowrap !important;
      font-family: "Pretendard Variable", Pretendard, -apple-system, sans-serif !important;
      flex: 0 0 auto !important;
    }
    .mh-toggle {
      display: flex !important;
      align-items: center !important;
      background: rgba(255,255,255,.08) !important;
      border: 1px solid rgba(255,255,255,.14) !important;
      border-radius: 100px !important;
      padding: 3px !important;
      gap: 2px !important;
      flex-shrink: 0 !important;
    }
    .mh-toggle a {
      padding: 4px 13px !important;
      border-radius: 100px !important;
      font-size: 10px !important;
      font-weight: 800 !important;
      letter-spacing: .07em !important;
      color: rgba(255,255,255,.45) !important;
      transition: all 200ms !important;
      text-decoration: none !important;
      font-family: "Pretendard Variable", Pretendard, -apple-system, sans-serif !important;
      white-space: nowrap !important;
    }
    .mh-toggle a.mh-on {
      background: #fff !important;
      color: #000 !important;
    }

    /* ── 플로팅 로그인 버튼 (iOS 네이티브 느낌) ── */
    #mh-float-auth {
      position: fixed !important;
      right: 16px !important;
      bottom: calc(90px + env(safe-area-inset-bottom, 0px)) !important;
      z-index: 9998 !important;
      display: flex !important;
      flex-direction: column !important;
      align-items: flex-end !important;
      gap: 10px !important;
      pointer-events: none !important;
      opacity: 0 !important;
      transform: translateY(12px) scale(.94) !important;
      transition: opacity .4s cubic-bezier(.22,1,.36,1), transform .4s cubic-bezier(.22,1,.36,1) !important;
    }
    #mh-float-auth.visible {
      pointer-events: auto !important;
      opacity: 1 !important;
      transform: translateY(0) scale(1) !important;
    }
    #mh-float-auth.mh-hidden {
      opacity: 0 !important;
      transform: translateY(12px) scale(.94) !important;
      pointer-events: none !important;
    }
    .mh-float-label {
      font-size: 11px !important;
      font-weight: 600 !important;
      color: rgba(255,255,255,.38) !important;
      letter-spacing: .01em !important;
      font-family: -apple-system, "Pretendard Variable", Pretendard, sans-serif !important;
      text-align: right !important;
      line-height: 1.4 !important;
      max-width: 160px !important;
      word-break: keep-all !important;
      transition: opacity .2s !important;
    }
    .mh-float-btn {
      display: flex !important;
      align-items: center !important;
      gap: 6px !important;
      border-radius: 980px !important;
      font-family: -apple-system, "Pretendard Variable", Pretendard, sans-serif !important;
      text-decoration: none !important;
      white-space: nowrap !important;
      cursor: pointer !important;
      -webkit-tap-highlight-color: transparent !important;
      transition: transform .16s cubic-bezier(.34,1.56,.64,1), opacity .12s !important;
    }
    .mh-float-btn:active { transform: scale(.93) !important; opacity: .82 !important; }
    .mh-float-login {
      padding: 13px 22px !important;
      font-size: 15px !important;
      font-weight: 600 !important;
      letter-spacing: -.01em !important;
      background: rgba(28,28,30,.72) !important;
      color: #fff !important;
      backdrop-filter: saturate(180%) blur(28px) !important;
      -webkit-backdrop-filter: saturate(180%) blur(28px) !important;
      border: 0.5px solid rgba(255,255,255,.2) !important;
      box-shadow: 0 2px 12px rgba(0,0,0,.3), 0 0 0 0.5px rgba(255,255,255,.08) inset !important;
    }
    .mh-float-user {
      padding: 12px 20px !important;
      font-size: 14px !important;
      font-weight: 600 !important;
      background: rgba(28,28,30,.72) !important;
      color: #4ade80 !important;
      backdrop-filter: saturate(180%) blur(28px) !important;
      -webkit-backdrop-filter: saturate(180%) blur(28px) !important;
      border: 0.5px solid rgba(74,222,128,.22) !important;
      box-shadow: 0 2px 12px rgba(0,0,0,.3) !important;
      display: none !important;
    }
    .mh-float-logout {
      padding: 10px 16px !important;
      font-size: 13px !important;
      font-weight: 500 !important;
      background: rgba(28,28,30,.65) !important;
      color: rgba(255,255,255,.45) !important;
      backdrop-filter: saturate(180%) blur(20px) !important;
      -webkit-backdrop-filter: saturate(180%) blur(20px) !important;
      border: 0.5px solid rgba(255,255,255,.1) !important;
      box-shadow: 0 2px 8px rgba(0,0,0,.2) !important;
      display: none !important;
    }
    .mh-float-logout:hover { color: #f87171 !important; border-color: rgba(248,113,113,.25) !important; }
    .mh-float-dot {
      width: 7px !important; height: 7px !important;
      border-radius: 50% !important;
      background: #4ade80 !important;
      flex-shrink: 0 !important;
      box-shadow: 0 0 8px rgba(74,222,128,.7) !important;
    }

    @media (max-width: 480px) {
      .site-nav-inner { padding: 11px 14px !important; }
      .nav-logo { font-size: 11px !important; letter-spacing: .04em !important; }
      .mh-toggle a { padding: 3px 9px !important; font-size: 9px !important; }
      #mh-float-auth { right: 16px !important; bottom: calc(24px + env(safe-area-inset-bottom, 0px)) !important; }
      .mh-float-btn { font-size: 12px !important; padding: 10px 16px !important; }
    }
  `;
  document.head.appendChild(style);

  /* ── PWA 모드: 네비 숨김 + safe-area + 드릴 영상 보호 ── */
  if (isStandalone) {
    const pwaStyle = document.createElement('style');
    pwaStyle.textContent = `
      .site-nav { display: none !important; }
      body { padding-top: env(safe-area-inset-top, 0px) !important; }
      .drill-video-wrap, .vimeo-wrap, iframe[src*="vimeo"], iframe[src*="player"] {
        margin-top: 0 !important;
      }
    `;
    document.head.appendChild(pwaStyle);
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', () => { buildFloatAuth(); initAuth(); });
    } else {
      buildFloatAuth(); initAuth();
    }
    return;
  }

  /* ── 네비 HTML ── */
  function buildNav() {
    if (isOnline) return;
    const nav = document.querySelector('.site-nav');
    if (!nav) return;

    nav.innerHTML = `
      <div class="site-nav-inner">
        <a href="${isOnline ? root + 'online_academy/index.html' : root + 'index.html'}" class="nav-logo">MONSTER HOOPS ACADEMY</a>
        <div class="mh-toggle">
          <a href="${root}index.html" class="${!isOnline ? 'mh-on' : ''}">OFFLINE</a>
          <a href="#" class="${isOnline ? 'mh-on' : ''}" id="mh-online-btn">ONLINE</a>
        </div>
      </div>
    `;

    // ONLINE 버튼: online_academy 밖에서는 모달, 안에서는 index로 이동
    const onlineBtn = document.getElementById('mh-online-btn');
    if (onlineBtn && !isOnline) {
      onlineBtn.addEventListener('click', function(e) {
        e.preventDefault();
        document.getElementById('mh-members-modal').style.display = 'flex';
      });
    } else if (onlineBtn && isOnline) {
      onlineBtn.href = root + 'online_academy/index.html';
    }

    // 모달 삽입 (중복 방지)
    if (!document.getElementById('mh-members-modal')) {
      const modal = document.createElement('div');
      modal.id = 'mh-members-modal';
      modal.style.cssText = 'display:none;position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,0.75);align-items:center;justify-content:center;';
      modal.innerHTML = `
        <div style="background:#fff;border-radius:12px;border:1px solid #222;padding:2rem;max-width:320px;width:90%;text-align:center;">
          <div style="width:48px;height:48px;border-radius:50%;background:#000;display:flex;align-items:center;justify-content:center;margin:0 auto 1rem;">
            <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
              <rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect>
              <path d="M7 11V7a5 5 0 0 1 10 0v4"></path>
            </svg>
          </div>
          <p style="font-size:11px;font-weight:500;letter-spacing:0.15em;text-transform:uppercase;color:#888;margin:0 0 8px;">Monster Hoops Academy</p>
          <p style="font-size:20px;font-weight:500;margin:0 0 12px;color:#000;">Members Only</p>
          <div style="width:32px;height:1px;background:#000;margin:0 auto 16px;"></div>
          <p style="font-size:13px;color:#555;margin:0 0 1.75rem;line-height:1.7;">온라인 아카데미는 회원 전용입니다.<br>가입 문의는 코치에게 연락해 주세요.</p>
          <button id="mh-members-close" style="width:100%;padding:11px;background:#000;color:#fff;border:none;border-radius:4px;font-size:13px;font-weight:500;letter-spacing:0.05em;cursor:pointer;">확인</button>
        </div>
      `;
      document.body.appendChild(modal);
      document.getElementById('mh-members-close').addEventListener('click', function() {
        modal.style.display = 'none';
      });
      modal.addEventListener('click', function(e) {
        if (e.target === modal) modal.style.display = 'none';
      });
    }

    // 교체 완료 후 페이드인 (FOUC 방지)
    requestAnimationFrame(() => nav.classList.add('mh-ready'));
  }

  /* ── 플로팅 버튼 ── */
  function buildFloatAuth() {
    if (!isOnline) return;
    // 드릴 상세 페이지에선 표시 안 함
    if (location.pathname.includes('drill.html') || location.pathname.includes('login.html')) return;

    const loginHref = `${root}online_academy/login.html`;

    const el = document.createElement('div');
    el.id = 'mh-float-auth';
    el.innerHTML = `
      <div class="mh-float-label" id="mh-float-label">Want to be a MONSTER?</div>
      <a href="${loginHref}" class="mh-float-btn mh-float-login" id="mh-float-login-btn">
        <span>시작하기</span>
      </a>
      <a href="admin-joohanlee.html" class="mh-float-btn mh-float-user" id="mh-float-admin-btn" style="display:none!important;background:rgba(74,222,128,.15)!important;color:#4ade80!important;border-color:rgba(74,222,128,.25)!important">⚡ ADMIN</a>
      <a href="mypage.html" class="mh-float-btn mh-float-user" id="mh-float-user-btn"></a>
      <button class="mh-float-btn mh-float-logout" id="mh-float-logout-btn" onclick="mhLogout()">로그아웃</button>
    `;
    document.body.appendChild(el);

    // 인증 확인 후 showFloat()가 visible 추가
  }

  /* ── Firebase Auth ── */
  function initAuth() {
    if (!isOnline) return;
    const base = new URL('./', document.baseURI).pathname;
    import(base + 'firebase-config.js').then(({ auth, db }) => {
      Promise.all([
        import('https://www.gstatic.com/firebasejs/10.12.0/firebase-auth.js'),
        import('https://www.gstatic.com/firebasejs/10.12.0/firebase-firestore.js'),
      ]).then(([{ onAuthStateChanged, signOut }, { doc, getDoc }]) => {

        window.mhLogout = async () => { await signOut(auth); };

        const ADMIN_EMAILS = ['monsterhoops.official@gmail.com'];

        onAuthStateChanged(auth, async user => {
          const loginBtn  = document.getElementById('mh-float-login-btn');
          const userBtn   = document.getElementById('mh-float-user-btn');
          const adminBtn  = document.getElementById('mh-float-admin-btn');
          const logoutBtn = document.getElementById('mh-float-logout-btn');
          const label     = document.getElementById('mh-float-label');

          if (user) {
            const isAdmin = ADMIN_EMAILS.includes(user.email);
            // Firestore에서 memberType + 프로필 확인
            let memberType = 'online';
            let userData = {};
            try {
              const snap = await getDoc(doc(db, 'users', user.uid));
              if (snap.exists()) {
                userData = snap.data();
                memberType = userData.memberType || 'online';
              }
            } catch(e) {}

            // 채널톡에 회원 실명 정보 업데이트
            if (window.ChannelIO) {
              ChannelIO('updateUser', {
                memberId: user.uid,
                profile: {
                  name: userData.nickname || user.displayName || '회원',
                  email: user.email || null,
                  mobileNumber: userData.phone || null,
                }
              });
            }

            // ── 모든 로그인 유저: FAB 표시 ──
            const floatEl = document.getElementById('mh-float-auth');
            if (floatEl) floatEl.classList.add('mh-hidden');
            buildAcademyTabBar(user, isAdmin, userData);
          } else {
            // ── 비로그인: 플로팅 버튼 표시 + FAB도 표시 ──
            if (loginBtn) loginBtn.style.removeProperty('display');
            if (userBtn)   userBtn.style.setProperty('display', 'none', 'important');
            if (adminBtn)  adminBtn.style.setProperty('display', 'none', 'important');
            if (logoutBtn) logoutBtn.style.setProperty('display', 'none', 'important');
            if (label) label.textContent = 'Want to be a MONSTER?';
            removeAcademyTabBar();
            const floatElGuest = document.getElementById('mh-float-auth');
            if (floatElGuest) { floatElGuest.classList.remove('mh-hidden'); setTimeout(() => floatElGuest.classList.add('visible'), 50); }
          }
        });
      });
    }).catch(() => {});
  }

  /* ── 아카데미 하단 탭바 ── */
  /* ── 아카데미 플로팅 FAB 메뉴 ── */
  function buildAcademyTabBar(user, isAdmin, userData = {}) {
    if (document.getElementById('mh-fab-wrap')) return;

    const path = location.pathname;
    const role = userData.role || '';

    // role별 수업 버튼 링크
    const CLASS_HREF_MAP = {
      admin:              'calendar.html',
      coach:              'calendar.html',
      elite_prep:         'elite_prep_schedule.html',
      elite_prep_parent:  'elite_prep_schedule.html',
      elite:              'player_development_schedule.html',
      elite_parent:       'player_development_schedule.html',
      pro:                'player_development_schedule.html',
      amateur:            'amateur_classes.html',
      membership:         'amateur_classes.html',
      free:               'amateur_classes.html',
    };
    const classHref = CLASS_HREF_MAP[role] || 'amateur_classes.html';

    // FAB 완전 제외 페이지 (콘텐츠 가독성)
    const noFabPages = ['drill.html', 'lecture-detail.html', 'login.html'];
    if (noFabPages.some(p => path.includes(p))) return;

    const isClasses  = path.includes('classes.html') || path.includes('schedule.html') || path.includes('calendar.html');
    const isChat     = path.includes('messages.html');
    const isMypage   = path.includes('mypage.html');
    const isLectures = path.includes('lectures.html');
    const isBlog     = path.includes('blog.html');
    const isHome     = path.endsWith('index.html') || path.endsWith('/') || path === '' || path.endsWith('/online_academy') || path.endsWith('/online_academy/');


    // 스타일 주입
    const st = document.createElement('style');
    st.id = 'mh-fab-style';
    st.textContent = `
      #mh-fab-wrap {
        position: fixed !important;
        right: 22px !important;
        left: auto !important;
        bottom: calc(28px + env(safe-area-inset-bottom, 0px)) !important;
        z-index: 9990 !important;
        display: flex !important;
        flex-direction: column;
        align-items: flex-end;
        gap: 12px;
        pointer-events: none !important;
      }
      #mh-fab-bottom-row {
        display: flex;
        align-items: center;
        gap: 10px;
        pointer-events: none !important;
      }
      #mh-fab-main, #mh-fab-home {
        pointer-events: auto !important;
      }
      /* 홈 pill 버튼 */
      #mh-fab-home {
        display: flex; align-items: center; gap: 5px;
        opacity: 0; pointer-events: none;
        transform: translateX(8px) scale(.9);
        background: rgba(28,28,30,.92);
        border: 1px solid rgba(255,255,255,.12);
        border-radius: 99px;
        padding: 9px 14px 9px 11px;
        color: rgba(255,255,255,.85);
        font-size: 13px; font-weight: 700;
        font-family: 'Pretendard Variable', sans-serif;
        cursor: pointer; -webkit-tap-highlight-color: transparent;
        backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px);
        box-shadow: 0 4px 16px rgba(0,0,0,.35);
        transition: transform .25s cubic-bezier(.34,1.56,.64,1), opacity .2s;
        text-decoration: none;
        letter-spacing: -.02em;
        white-space: nowrap;
      }
      #mh-fab-home:active { transform: scale(.93); opacity: .8; }
      #mh-fab-home svg { opacity: .6; width: 13px; height: 13px; }
      /* 메인 FAB */
      #mh-fab-main {
        width: 54px; height: 54px; border-radius: 50%;
        background: transparent;
        display: flex; align-items: center; justify-content: center;
        cursor: pointer; -webkit-tap-highlight-color: transparent;
        box-shadow: none;
        transition: transform .35s cubic-bezier(.34,1.56,.64,1), box-shadow .2s;
        position: relative; z-index: 2;
        overflow: hidden;
      }
      #mh-fab-main.open { transform: scale(.88); box-shadow: 0 2px 12px rgba(0,0,0,.4); }
      #mh-fab-main img { width: 80%; height: 80%; object-fit: contain; border-radius: 0; transition: transform .35s cubic-bezier(.34,1.56,.64,1); }
      #mh-fab-main.open img { transform: scale(.75) rotate(15deg); }
      /* 메뉴 아이템 */
      .mh-fab-item {
        display: flex; flex-direction: column; align-items: center; gap: 5px;
        opacity: 0; transform: translateY(16px) scale(.8);
        transition: opacity .25s, transform .3s cubic-bezier(.34,1.56,.64,1);
        pointer-events: none; cursor: pointer;
        -webkit-tap-highlight-color: transparent;
        text-decoration: none;
      }
      .mh-fab-item.visible { opacity: 1; transform: translateY(0) scale(1); pointer-events: auto; }
      .mh-fab-icon {
        width: 46px; height: 46px; border-radius: 50%;
        background: rgba(44,44,46,.96);
        border: 1px solid rgba(255,255,255,.1);
        backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px);
        display: flex; align-items: center; justify-content: center;
        box-shadow: 0 4px 16px rgba(0,0,0,.4);
        transition: transform .15s, background .15s;
      }
      .mh-fab-icon.active { background: rgba(74,222,128,.18); border-color: rgba(74,222,128,.3); }
      .mh-fab-item:active .mh-fab-icon { transform: scale(.9); }
      .mh-fab-label {
        font-size: 11px; font-weight: 800; color: rgba(255,255,255,.75);
        font-family: 'Pretendard Variable', sans-serif;
        letter-spacing: -.02em;
        text-shadow: 0 1px 4px rgba(0,0,0,.8);
      }
      /* 오버레이 */
      #mh-fab-overlay {
        position: fixed; inset: 0; z-index: 9989;
        display: none;
      }
      /* 플로팅 버튼 숨기기 */
      #mh-float-auth { display: none !important; }
    `;
    document.head.appendChild(st);

    // 오버레이
    const overlay = document.createElement('div');
    overlay.id = 'mh-fab-overlay';
    overlay.addEventListener('click', closeFab);
    document.body.appendChild(overlay);

    // FAB 래퍼
    const wrap = document.createElement('div');
    wrap.id = 'mh-fab-wrap';

    const DEPTH2_PAGES = [
      'lecture-detail.html',
      'drill.html',
      'program.html',
      'live-streaming.html',
      'blog.html',
      'shop.html',
      'payment.html',
      'payment-success.html',
      'payment-fail.html',
      'session-success.html',
    ];
    const isDepth2 = DEPTH2_PAGES.some(p => path.includes(p));

    const ITEMS = [
      { href: 'mypage.html',  label: '라커룸',  active: isMypage,  action: null,
        svg: '<svg width="20" height="20" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="8" r="4" stroke="currentColor" stroke-width="1.8"/><path d="M4 20C4 17 7.58 14 12 14C16.42 14 20 17 20 20" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>' },
      { href: null,           label: 'DM',  active: false,     action: 'channeltalk',
        svg: '<svg width="20" height="20" viewBox="0 0 24 24" fill="none"><path d="M21 15C21 15.55 20.55 16 20 16H8L4 20V5C4 4.45 4.45 4 5 4H20C20.55 4 21 4.45 21 5V15Z" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/></svg>' },
      // 캘린더: 어드민/코치만 표시 (일정 구조 정리 전까지 비활성)
      ...(isAdmin ? [{ href: classHref, label: '캘린더', active: isClasses, action: null,
        svg: '<svg width="20" height="20" viewBox="0 0 24 24" fill="none"><rect x="3" y="4" width="18" height="18" rx="3" stroke="currentColor" stroke-width="1.8"/><path d="M16 2V6M8 2V6M3 10H21" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>' }] : []),
      ...(isAdmin ? [{ href: null, label: '푸시알림', active: false, action: 'push-notify',
        svg: '<svg width="20" height="20" viewBox="0 0 24 24" fill="none"><path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/><path d="M13.73 21a2 2 0 0 1-3.46 0" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>' }] : []),
    ];



    // 메뉴 아이템 (위에서 아래 순서로 DOM에 추가, 가장 위 = 마이)
    const itemEls = ITEMS.map((item, i) => {
      const a = document.createElement('a');
      a.className = 'mh-fab-item';
      if (item.action === 'channeltalk') {
        a.href = '#';
        a.style.position = 'relative';
        // 뱃지 DOM
        const badge = document.createElement('span');
        badge.id = 'mh-dm-badge';
        badge.style.cssText = `
          position:absolute; top:4px; right:6px;
          min-width:16px; height:16px; border-radius:8px;
          background:#f87171; display:none;
          box-shadow:0 0 0 2px rgba(0,0,0,.6);
          font-size:10px; font-weight:900; color:#fff;
          line-height:16px; text-align:center; padding:0 4px;
          font-family:-apple-system,sans-serif;
        `;
        a.appendChild(badge);
        a.addEventListener('click', e => { e.preventDefault(); if(window.ChannelIO) ChannelIO('showMessenger'); closeFab(); });

        // 뱃지 업데이트 함수
        function updateBadge(count) {
          if (count > 0) {
            badge.style.display = 'block';
            badge.textContent = count > 99 ? '99+' : count;
          } else {
            badge.style.display = 'none';
            badge.textContent = '';
          }
        }

        // 부트 전에 이미 저장된 count가 있으면 즉시 반영
        if (window._mhUnreadCount > 0) updateBadge(window._mhUnreadCount);

        // 리스너 등록 함수
        function registerBadgeListener() {
          if (window.ChannelIO) {
            ChannelIO('onBadgeChanged', updateBadge);
          }
        }

        registerBadgeListener();
        window.addEventListener('channelIOReady', registerBadgeListener);
        setTimeout(registerBadgeListener, 1000);
        setTimeout(registerBadgeListener, 3000);
      } else if (item.action === 'back') {
        a.href = '#';
        a.addEventListener('click', e => { e.preventDefault(); history.back(); closeFab(); });
      } else if (item.action === 'push-notify') {
        a.href = '#';
        a.addEventListener('click', e => { e.preventDefault(); closeFab(); if(window.openPushModal) window.openPushModal(); });
      } else {
        a.href = item.href;
      }
      a.innerHTML = `
        <div class="mh-fab-icon ${item.active ? 'active' : ''}" style="color:${item.active ? '#4ade80' : 'rgba(255,255,255,.8)'}">
          ${item.svg}
        </div>
        <span class="mh-fab-label">${item.label}</span>
      `;
      wrap.appendChild(a);
      return a;
    });

    // 메인 FAB 버튼 (맨 아래)
    const main = document.createElement('div');
    main.id = 'mh-fab-main';
    main.innerHTML = `<img src="data:image/png;base64," alt="menu" draggable="false">`;
    main.addEventListener('click', () => {
      const isOpen = main.classList.contains('open');
      isOpen ? closeFab() : openFab();
    });
    // 하단 행: 홈/뒤로 pill 버튼 + FAB 메인
    const bottomRow = document.createElement('div');
    bottomRow.id = 'mh-fab-bottom-row';

    if (!isHome) {
      const homeBtn = document.createElement('a');
      homeBtn.id = 'mh-fab-home';
      if (isDepth2) {
        homeBtn.href = '#';
        homeBtn.innerHTML = `<svg width="13" height="13" viewBox="0 0 24 24" fill="none"><path d="M15 19L8 12L15 5" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>뒤로`;
        homeBtn.addEventListener('click', e => { e.preventDefault(); history.back(); });
      } else {
        homeBtn.href = 'index.html';
        homeBtn.innerHTML = `<svg width="13" height="13" viewBox="0 0 24 24" fill="none"><path d="M15 19L8 12L15 5" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>홈으로`;
      }
      bottomRow.appendChild(homeBtn);
    }

    bottomRow.appendChild(main);
    wrap.appendChild(bottomRow);
    document.body.appendChild(wrap);
    window.dispatchEvent(new Event('mhFabReady'));

    function openFab() {
      main.classList.add('open');
      overlay.style.display = 'block';
      itemEls.forEach((el, i) => {
        setTimeout(() => el.classList.add('visible'), i * 40);
      });
      const homeBtn = document.getElementById('mh-fab-home');
      if (homeBtn) setTimeout(() => {
        homeBtn.style.opacity = '1';
        homeBtn.style.pointerEvents = 'auto';
        homeBtn.style.transform = 'translateX(0) scale(1)';
      }, itemEls.length * 40);
    }
    function closeFab() {
      main.classList.remove('open');
      overlay.style.display = 'none';
      itemEls.forEach(el => el.classList.remove('visible'));
      const homeBtn = document.getElementById('mh-fab-home');
      if (homeBtn) {
        homeBtn.style.opacity = '0';
        homeBtn.style.pointerEvents = 'none';
        homeBtn.style.transform = 'translateX(8px) scale(.9)';
      }
    }
    window._mhCloseFab = closeFab;

    // 슬라이드 인 애니메이션
    wrap.style.opacity = '0';
    wrap.style.transform = 'scale(.7)';
    wrap.style.transition = 'opacity .35s cubic-bezier(.22,1,.36,1), transform .35s cubic-bezier(.22,1,.36,1)';
    requestAnimationFrame(() => requestAnimationFrame(() => {
      wrap.style.opacity = '1';
      wrap.style.transform = 'scale(1)';
    }));
  }

  function removeAcademyTabBar() {
    document.getElementById('mh-fab-wrap')?.remove();
    document.getElementById('mh-fab-overlay')?.remove();
    document.getElementById('mh-fab-style')?.remove();
  }

  /* 훈련 모드 진입 시 플로팅 버튼 숨기기 노출용 전역 함수 */
  window.mhHideFloat  = () => { const el = document.getElementById('mh-float-auth'); if(el) el.classList.add('mh-hidden'); };
  window.mhShowFloat  = () => { const el = document.getElementById('mh-float-auth'); if(el) el.classList.remove('mh-hidden'); };
  window.mhHideFab    = () => { const el = document.getElementById('mh-fab-wrap'); if(el){ el.style.opacity='0'; el.style.transform='scale(.8)'; } };
  window.mhShowFab    = () => { const el = document.getElementById('mh-fab-wrap'); if(el){ el.style.opacity='1'; el.style.transform='scale(1)'; } };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => { buildNav(); buildFloatAuth(); initAuth(); });
  } else {
    buildNav(); buildFloatAuth(); initAuth();
  }

})();

// ── 엣지 스와이프 뒤로가기 ──
(function() {
  const BACK_MAP = {
    'routines.html':                   'index.html',
    'routine-library.html':            'routines.html',
    'routine-admin.html':              'routines.html',
    'ai-management.html':              'index.html',
    'ai-coach.html':                   'index.html',
    'ai-mental.html':                  'index.html',
    'ai-recovery.html':                'index.html',
    'journals.html':                   'index.html',
    'journal.html':                    'journals.html',
    'lectures.html':                   'index.html',
    'lecture-detail.html':             'lectures.html',
    'drills.html':                     'index.html',
    'programs.html':                   'index.html',
    'program.html':                    'programs.html',
    'blog.html':                       'index.html',
    'mypage.html':                     'index.html',
    'classes.html':                    'index.html',
    'amateur_classes.html':            'index.html',
    'elite_prep_schedule.html':        'index.html',
    'player_development_schedule.html':'index.html',
    'calendar.html':                   'index.html',
    'schedule.html':                   'index.html',
    'elite-prep.html':                 'index.html',
    'shop.html':                       'index.html',
    'payment.html':                    'shop.html',
    'payment-fail.html':               'payment.html',
    'vocab.html':                      'index.html',
    'shuttle.html':                    'index.html',
    'shuttle-driver.html':             'index.html',
    'messages.html':                   'index.html',
    'live-streaming.html':             'index.html',
    'admin-joohanlee.html':            'index.html',
    'seed-routines.html':              'index.html',
  };

  function getCurrentPage() {
    return location.pathname.split('/').pop() || 'index.html';
  }

  function getBackUrl() {
    var page = getCurrentPage();
    // drill.html은 ?program= 파라미터 있으면 program.html로
    if (page === 'drill.html') {
      var programId = new URLSearchParams(location.search).get('program');
      return programId ? ('program.html?id=' + programId) : 'drills.html';
    }
    return BACK_MAP[page] || null;
  }

  // index.html이거나 매핑 없는 페이지면 스와이프 백 비활성화
  // lecture-detail.html은 자체 goBack() 있으니 위임
  var SKIP_PAGES = ['index.html', 'login.html', 'payment-success.html', 'session-success.html', 'lecture-detail.html'];

  var touchStartX = 0;
  var touchStartY = 0;
  var swipeTracking = false;

  document.addEventListener('touchstart', function(e) {
    var page = getCurrentPage();
    if (SKIP_PAGES.includes(page)) return;
    if (!getBackUrl()) return;
    touchStartX = e.touches[0].clientX;
    touchStartY = e.touches[0].clientY;
    // 왼쪽 엣지 30px 이내에서만 시작
    swipeTracking = touchStartX <= 30;
  }, { passive: true });

  document.addEventListener('touchend', function(e) {
    if (!swipeTracking) return;
    swipeTracking = false;
    var dx = e.changedTouches[0].clientX - touchStartX;
    var dy = Math.abs(e.changedTouches[0].clientY - touchStartY);
    // 오른쪽으로 80px 이상, 세로 이동보다 가로 이동이 커야 함
    if (dx > 80 && dx > dy * 1.5) {
      var backUrl = getBackUrl();
      if (backUrl) location.href = backUrl;
    }
  }, { passive: true });
})();
